<p>
<script>
    // Variables globales
    let invMatrix = [[0,0,1,0], [0,0,0,1]];
    const EPSILON = 0.0001; // Para comparar decimales

    // Parser de fracciones introducidas por el usuario
    function parseFrac(valStr) {
        if(!valStr || valStr.trim() === '') return NaN;
        if(valStr.includes('/')) {
            let parts = valStr.split('/');
            if(parts.length !== 2) return NaN;
            return parseFloat(parts[0]) / parseFloat(parts[1]);
        }
        return parseFloat(valStr);
    }

    // Convertidor Visual: De Decimal a Fracción HTML
    function formatFracVisual(val) {
        if (Math.abs(Math.round(val) - val) < EPSILON) {
            return Math.round(val).toString();
        }
        let sign = val < 0 ? "-" : "";
        let x = Math.abs(val);
        // Busca la fracción más exacta (hasta denominador 500)
        for (let d = 1; d <= 500; d++) {
            let n = Math.round(x * d);
            if (Math.abs(x - n/d) < EPSILON) {
                return `${sign}<div style="display:inline-block; text-align:center; vertical-align:middle; font-size:0.9em; margin:0 2px;"><span style="display:block; line-height:1;">${n}</span><span style="display:block; line-height:1; border-top:1px solid #333;">${d}</span></div>`;
            }
        }
        // Fallback si es un decimal no periódico extraño
        return parseFloat(val.toFixed(3));
    }

    // Comprobar igualdad con margen de error
    function epsEqual(a, b) {
        return Math.abs(a - b) < EPSILON;
    }

    // Generar matriz 2x2 invertible
    function invGenerar() {
        let isNat = document.querySelector('input[name="inv-tipo"]:checked').value === 'nat';
        let valid = false;

        while(!valid) {
            for(let i=0; i<2; i++) {
                for(let j=0; j<2; j++) {
                    let val = isNat ? Math.floor(Math.random() * 9) + 1 : Math.floor(Math.random() * 19) - 9;
                    invMatrix[i][j] = val;
                }
            }
            // Reset identidad
            invMatrix[0][2] = 1; invMatrix[0][3] = 0;
            invMatrix[1][2] = 0; invMatrix[1][3] = 1;

            let det = (invMatrix[0][0]*invMatrix[1][1]) - (invMatrix[0][1]*invMatrix[1][0]);
            if(det !== 0 && invMatrix[0][0] !== 0) valid = true;
        }

        invUpdateDisplay();
        invResetUI();
    }

    // Actualizar números en pantalla
    function invUpdateDisplay() {
        for(let i=0; i<2; i++) {
            for(let j=0; j<4; j++) {
                let cell = document.getElementById(`inv-m${i}${j}`);
                // Ahora usamos innerHTML para inyectar la estructura CSS de la fracción
                cell.innerHTML = formatFracVisual(invMatrix[i][j]);
                cell.style.color = "#333";
                cell.style.fontWeight = "normal";
            }
        }
    }

    // Resaltar celdas (pivote y objetivo)
    function invHighlight(pivotRow, pivotCol, targetRow, targetCol, colorPiv, colorTarg) {
        invUpdateDisplay();
        document.getElementById(`inv-m${pivotRow}${pivotCol}`).style.color = colorPiv;
        document.getElementById(`inv-m${pivotRow}${pivotCol}`).style.fontWeight = "bold";
        if(targetRow !== null) {
            document.getElementById(`inv-m${targetRow}${targetCol}`).style.color = colorTarg;
            document.getElementById(`inv-m${targetRow}${targetCol}`).style.fontWeight = "bold";
        }
    }

    // Limpiar interfaz
    function invResetUI() {
        document.getElementById('inv-paso1').style.display = 'block';
        document.getElementById('inv-paso2').style.display = 'none';
        document.getElementById('inv-paso3').style.display = 'none';
        document.getElementById('inv-paso4').style.display = 'none';

        let inputs = document.querySelectorAll('#inversa-tutor input[type="text"]');
        inputs.forEach(inp => { inp.value = ''; inp.disabled = false; });

        let btns = document.querySelectorAll('#inversa-tutor .inv-btn-check');
        btns.forEach(btn => btn.disabled = false);

        let feedbacks = document.querySelectorAll('#inversa-tutor .inv-feedback');
        feedbacks.forEach(fb => fb.innerHTML = '');

        document.getElementById('row-p1').style.display = 'none';
        document.getElementById('row-p2').style.display = 'none';
        document.getElementById('row-p3a').style.display = 'none';
        document.getElementById('row-p3b').style.display = 'none';

        invHighlight(0, 0, 1, 0, "#f57c00", "#dc3545"); // Resalta a11 y a21
    }

    // --- PASO 1 ---
    function invCheckOp1() {
        let k1 = parseFrac(document.getElementById('s1-kf1').value);
        let k2 = parseFrac(document.getElementById('s1-kf2').value);
        let fb = document.getElementById('res-op-1');

        if(isNaN(k1) || isNaN(k2)) { fb.innerHTML = '<span class="inv-error">Completa campos</span>'; return; }
        if(k2 === 0) { fb.innerHTML = '<span class="inv-error">k2 no puede ser 0</span>'; return; }

        let res = (k1 * invMatrix[0][0]) + (k2 * invMatrix[1][0]);
        if(epsEqual(res, 0)) {
            fb.innerHTML = '<span class="inv-success">¡Correcto!</span>';
            document.getElementById('row-p1').style.display = 'flex';
            document.getElementById('s1-kf1').disabled = true; document.getElementById('s1-kf2').disabled = true;
        } else {
            fb.innerHTML = '<span class="inv-error">No da 0</span>';
        }
    }

    function invCheckRow1() {
        let k1 = parseFrac(document.getElementById('s1-kf1').value);
        let k2 = parseFrac(document.getElementById('s1-kf2').value);
        let fb = document.getElementById('res-row-1');

        let userRow = [
            parseFrac(document.getElementById('s1-r0').value), parseFrac(document.getElementById('s1-r1').value),
            parseFrac(document.getElementById('s1-r2').value), parseFrac(document.getElementById('s1-r3').value)
        ];

        if(userRow.some(isNaN)) { fb.innerHTML = '<span class="inv-error">Faltan datos</span>'; return; }

        let isCorrect = true;
        let realRow = [];
        for(let j=0; j<4; j++) {
            realRow[j] = (k1 * invMatrix[0][j]) + (k2 * invMatrix[1][j]);
            if(!epsEqual(userRow[j], realRow[j])) isCorrect = false;
        }

        if(isCorrect) {
            fb.innerHTML = '<span class="inv-success">¡Perfecto!</span>';
            invMatrix[1] = realRow;
            invUpdateDisplay();
            ['s1-r0','s1-r1','s1-r2','s1-r3'].forEach(id => document.getElementById(id).disabled = true);
            document.getElementById('inv-paso2').style.display = 'block';
            invHighlight(1, 1, 0, 1, "#e65100", "#dc3545"); // Resalta a22 y a12
        } else {
            fb.innerHTML = '<span class="inv-error">Error de cálculo</span>';
        }
    }

    // --- PASO 2 ---
    function invCheckOp2() {
        let k2 = parseFrac(document.getElementById('s2-kf2').value);
        let k1 = parseFrac(document.getElementById('s2-kf1').value);
        let fb = document.getElementById('res-op-2');

        if(isNaN(k2) || isNaN(k1)) { fb.innerHTML = '<span class="inv-error">Completa campos</span>'; return; }
        if(k1 === 0) { fb.innerHTML = '<span class="inv-error">k1 no puede ser 0</span>'; return; }

        let res = (k2 * invMatrix[1][1]) + (k1 * invMatrix[0][1]);
        if(epsEqual(res, 0)) {
            fb.innerHTML = '<span class="inv-success">¡Correcto!</span>';
            document.getElementById('row-p2').style.display = 'flex';
            document.getElementById('s2-kf2').disabled = true; document.getElementById('s2-kf1').disabled = true;
        } else {
            fb.innerHTML = '<span class="inv-error">No da 0</span>';
        }
    }

    function invCheckRow2() {
        let k2 = parseFrac(document.getElementById('s2-kf2').value);
        let k1 = parseFrac(document.getElementById('s2-kf1').value);
        let fb = document.getElementById('res-row-2');

        let userRow = [
            parseFrac(document.getElementById('s2-r0').value), parseFrac(document.getElementById('s2-r1').value),
            parseFrac(document.getElementById('s2-r2').value), parseFrac(document.getElementById('s2-r3').value)
        ];

        if(userRow.some(isNaN)) { fb.innerHTML = '<span class="inv-error">Faltan datos</span>'; return; }

        let isCorrect = true;
        let realRow = [];
        for(let j=0; j<4; j++) {
            realRow[j] = (k2 * invMatrix[1][j]) + (k1 * invMatrix[0][j]);
            if(!epsEqual(userRow[j], realRow[j])) isCorrect = false;
        }

        if(isCorrect) {
            fb.innerHTML = '<span class="inv-success">¡Perfecto!</span>';
            invMatrix[0] = realRow;
            invUpdateDisplay();
            ['s2-r0','s2-r1','s2-r2','s2-r3'].forEach(id => document.getElementById(id).disabled = true);
            document.getElementById('inv-paso3').style.display = 'block';
            invHighlight(0, 0, null, null, "#ff9800", null); // Resalta a11
        } else {
            fb.innerHTML = '<span class="inv-error">Error de cálculo</span>';
        }
    }

    // --- PASO 3a (F1) ---
    function invCheckOp3a() {
        let k = parseFrac(document.getElementById('s3a-k').value);
        let fb = document.getElementById('res-op-3a');
        if(isNaN(k)) return;

        if(epsEqual(k * invMatrix[0][0], 1)) {
            fb.innerHTML = '<span class="inv-success">¡Correcto!</span>';
            document.getElementById('row-p3a').style.display = 'flex';
            document.getElementById('s3a-k').disabled = true;
        } else {
            fb.innerHTML = '<span class="inv-error">No da 1</span>';
        }
    }

    function invCheckRow3a() {
        let k = parseFrac(document.getElementById('s3a-k').value);
        let fb = document.getElementById('res-row-3a');
        let uR = [parseFrac(document.getElementById('s3a-r0').value), parseFrac(document.getElementById('s3a-r1').value), parseFrac(document.getElementById('s3a-r2').value), parseFrac(document.getElementById('s3a-r3').value)];
        if(uR.some(isNaN)) return;

        let isCorrect = true, realRow = [];
        for(let j=0; j<4; j++) {
            realRow[j] = k * invMatrix[0][j];
            if(!epsEqual(uR[j], realRow[j])) isCorrect = false;
        }

        if(isCorrect) {
            fb.innerHTML = '<span class="inv-success">¡OK!</span>';
            invMatrix[0] = realRow;
            invUpdateDisplay();
            ['s3a-r0','s3a-r1','s3a-r2','s3a-r3'].forEach(id => document.getElementById(id).disabled = true);
            invHighlight(1, 1, null, null, "#ff9800", null); // Resalta a22
            checkFinish();
        } else {
            fb.innerHTML = '<span class="inv-error">Error</span>';
        }
    }

    // --- PASO 3b (F2) ---
    function invCheckOp3b() {
        let k = parseFrac(document.getElementById('s3b-k').value);
        let fb = document.getElementById('res-op-3b');
        if(isNaN(k)) return;

        if(epsEqual(k * invMatrix[1][1], 1)) {
            fb.innerHTML = '<span class="inv-success">¡Correcto!</span>';
            document.getElementById('row-p3b').style.display = 'flex';
            document.getElementById('s3b-k').disabled = true;
        } else {
            fb.innerHTML = '<span class="inv-error">No da 1</span>';
        }
    }

    function invCheckRow3b() {
        let k = parseFrac(document.getElementById('s3b-k').value);
        let fb = document.getElementById('res-row-3b');
        let uR = [parseFrac(document.getElementById('s3b-r0').value), parseFrac(document.getElementById('s3b-r1').value), parseFrac(document.getElementById('s3b-r2').value), parseFrac(document.getElementById('s3b-r3').value)];
        if(uR.some(isNaN)) return;

        let isCorrect = true, realRow = [];
        for(let j=0; j<4; j++) {
            realRow[j] = k * invMatrix[1][j];
            if(!epsEqual(uR[j], realRow[j])) isCorrect = false;
        }

        if(isCorrect) {
            fb.innerHTML = '<span class="inv-success">¡OK!</span>';
            invMatrix[1] = realRow;
            invUpdateDisplay();
            ['s3b-r0','s3b-r1','s3b-r2','s3b-r3'].forEach(id => document.getElementById(id).disabled = true);
            checkFinish();
        } else {
            fb.innerHTML = '<span class="inv-error">Error</span>';
        }
    }

    // Comprobar finalización e inyectar la matriz solución
    function checkFinish() {
        if(epsEqual(invMatrix[0][0], 1) && epsEqual(invMatrix[1][1], 1)) {
            document.getElementById('inv-paso4').style.display = 'block';

            // Inyectar fracciones visuales en la matriz final
            document.getElementById('inv-fm00').innerHTML = formatFracVisual(invMatrix[0][2]);
            document.getElementById('inv-fm01').innerHTML = formatFracVisual(invMatrix[0][3]);
            document.getElementById('inv-fm10').innerHTML = formatFracVisual(invMatrix[1][2]);
            document.getElementById('inv-fm11').innerHTML = formatFracVisual(invMatrix[1][3]);

            invUpdateDisplay(); // Limpia highlights
        }
    }

    // Iniciar
    invGenerar();
</script>
