<div id="row-p1b" style="display: none; align-items: center; gap: 10px;">Nueva F<sub>3</sub> = ( <input type="text" id="s1-r30" class="sys-input-val" /> <input type="text" id="s1-r31" class="sys-input-val" /> <input type="text" id="s1-r32" class="sys-input-val" /> | <input type="text" id="s1-r33" class="sys-input-val" /> ) <button onclick="sysCheckRow(2, 0, 's1-k3', 's1-k1b', ['s1-r30','s1-r31','s1-r32','s1-r33'], 'res-row-1b', 1)" class="sys-btn-check">¿Bien?</button> <span id="res-row-1b" class="sys-feedback"></span></div>
</div>
</div>
</div>
<!-- PASO 2: Cero en la segunda columna -->
<div id="sys-paso2" class="sys-paso-box" style="display: none; width: 100%; max-width: 850px; background: #fff; border: 1px solid #ffe0b2; border-left: 5px solid #f57c00; border-radius: 6px; padding: 20px; margin-bottom: 20px;">
<div style="font-weight: bold; color: #f57c00; margin-bottom: 15px; font-size: 1.1em;">2. Hacemos ceros en la segunda columna</div>
