<div class="sys-operacion"><input type="text" id="s2-k3" class="sys-input-coef" /> · F<sub>3</sub> + <input type="text" id="s2-k2" class="sys-input-coef" /> · F<sub>2</sub> → F<sub>3</sub> <button onclick="sysCheckOp(2, 1, 's2-k3', 's2-k2', 'res-op-2', 'row-p2')" class="sys-btn-check">¿Bien?</button> <span id="res-op-2" class="sys-feedback"></span></div>
<div id="row-p2" style="display: none; align-items: center; gap: 10px;">Nueva F<sub>3</sub> = ( <input type="text" id="s2-r30" class="sys-input-val" /> <input type="text" id="s2-r31" class="sys-input-val" /> <input type="text" id="s2-r32" class="sys-input-val" /> | <input type="text" id="s2-r33" class="sys-input-val" /> ) <button onclick="sysCheckRow(2, 1, 's2-k3', 's2-k2', ['s2-r30','s2-r31','s2-r32','s2-r33'], 'res-row-2', 2)" class="sys-btn-check">¿Bien?</button> <span id="res-row-2" class="sys-feedback"></span></div>
</div>
